//! Subtle, butter-themed sound effects, timed to the panel's animations.
//! The sounds are generated by scripts/make_sounds.py and built into the app.
//! Playback goes through the OS's own audio API (no audio library, nothing
//! running when silent), and respects the "Sounds" setting.

use tauri::{AppHandle, Manager};

use crate::app::AppState;

const OPEN: &[u8] = include_bytes!("../sounds/open.wav");
const TICK: &[u8] = include_bytes!("../sounds/tick.wav");
const MELT: &[u8] = include_bytes!("../sounds/melt.wav");
const FREED: &[u8] = include_bytes!("../sounds/freed.wav");
const CLOSE: &[u8] = include_bytes!("../sounds/close.wav");

/// Only these names can be played; the panel can't pass in arbitrary audio.
fn clip(name: &str) -> Option<(&'static str, &'static [u8])> {
    Some(match name {
        "open" => ("open", OPEN),
        "tick" => ("tick", TICK),
        "melt" => ("melt", MELT),
        "freed" => ("freed", FREED),
        "close" => ("close", CLOSE),
        _ => return None,
    })
}

pub fn enabled(app: &AppHandle) -> bool {
    app.try_state::<AppState>()
        .map(|s| s.settings.lock().map(|g| g.sounds).unwrap_or(true))
        .unwrap_or(false)
}

/// Plays a named effect if sounds are on. Returns right away.
pub fn play(app: &AppHandle, name: &str) {
    if !enabled(app) {
        return;
    }
    if let Some((id, bytes)) = clip(name) {
        imp::play(app, id, bytes);
    }
}

#[tauri::command]
pub fn play_sound(app: AppHandle, name: String) {
    play(&app, &name);
}

#[cfg(target_os = "macos")]
mod imp {
    use std::collections::HashMap;
    use std::sync::Mutex;

    use objc2::rc::Retained;
    use objc2::{AnyThread, MainThreadMarker};
    use objc2_app_kit::NSSound;
    use objc2_foundation::NSData;
    use tauri::AppHandle;

    struct Sounds(HashMap<&'static str, Retained<NSSound>>);
    // SAFETY: the sounds are only created and touched on the main thread
    // (every access goes through `run_on_main_thread`); the mutex just gives
    // us a place to keep them between plays.
    unsafe impl Send for Sounds {}

    static CACHE: Mutex<Option<Sounds>> = Mutex::new(None);

    pub fn play(app: &AppHandle, id: &'static str, bytes: &'static [u8]) {
        let _ = app.run_on_main_thread(move || {
            let Some(_mtm) = MainThreadMarker::new() else { return };
            let mut cache = CACHE.lock().unwrap_or_else(|e| e.into_inner());
            let sounds = cache.get_or_insert_with(|| Sounds(HashMap::new()));
            let sound = sounds.0.entry(id).or_insert_with(|| {
                let data = NSData::with_bytes(bytes);
                NSSound::initWithData(NSSound::alloc(), &data).expect("built-in sound decodes")
            });
            // Restart if it's still playing from a moment ago.
            sound.stop();
            sound.play();
        });
    }
}

#[cfg(windows)]
mod imp {
    use tauri::AppHandle;
    use windows::Win32::Media::Audio::{PlaySoundW, SND_ASYNC, SND_MEMORY, SND_NODEFAULT};
    use windows::core::PCWSTR;

    pub fn play(_app: &AppHandle, _id: &'static str, bytes: &'static [u8]) {
        // SAFETY: SND_MEMORY reads the WAV from `bytes`, which is 'static, so
        // it outlives the asynchronous playback.
        unsafe {
            let _ = PlaySoundW(PCWSTR(bytes.as_ptr().cast()), None, SND_MEMORY | SND_ASYNC | SND_NODEFAULT);
        }
    }
}

#[cfg(not(any(target_os = "macos", windows)))]
mod imp {
    use tauri::AppHandle;
    pub fn play(_app: &AppHandle, _id: &'static str, _bytes: &'static [u8]) {}
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_known_sounds() {
        assert!(clip("melt").is_some());
        assert!(clip("../../etc/passwd").is_none());
        assert!(clip("").is_none());
        for (_, bytes) in ["open", "tick", "melt", "freed", "close"].iter().filter_map(|n| clip(n)) {
            assert_eq!(&bytes[..4], b"RIFF");
            assert_eq!(&bytes[8..12], b"WAVE");
        }
    }
}
